// ---------- cases part 11 (added 10/10 from the code audit): AE pipeline/today/profile · AF onboarding & hand-offs · AH admin & header ----------
// Uses G_NEW, SA, D210 from cases_9.js.

// ================= AE · Pipeline / Today / profile features never tested =================
CASES.push({ id: "AE", group: G_NEW, short: { vi: "Pipeline, Today, hồ sơ: phần chưa test", en: "Pipeline, Today, profile: untested parts" },
  title: { vi: "Pipeline, My work today và hồ sơ: các tính năng đã ship nhưng chưa có bước test", en: "Pipeline, My work today and profile: shipped features with no test step yet" },
  goal: { vi: "Bộ lọc đã lưu, archive hàng loạt, copy, Board, label, phát lead khi hàng đợi trống, lọc Activity, follow-up, tên pháp lý, Edit profile, mục Sync, Cold list phân trang, tin nhắn ghim, Focus.", en: "Saved filters, bulk archive, copy, Board, labels, the empty-queue hand-out, Activity filter, follow-ups, legal name, Edit profile, the Sync section, Cold list paging, message pins, Focus mode." },
  acc: ["rec", "mgr", "recSms", "roleOfr"], res: ["register"],
  loNote: { vi: "Đăng ký trước NAE1–NAE5 (★ mục 5). Recruiter claim NAE3, NAE4, NAE5 ở Hot leads. NAE1 + NAE2 để nguyên (Manager archive ở AE2).", en: "Register NAE1–NAE5 first (★ item 5). The recruiter claims NAE3, NAE4, NAE5 in Hot leads. Leave NAE1 + NAE2 as they are (the Manager archives them in AE2)." },
  steps: [
    S("AE1", "REC", "<code>recruit.viet18.com/pipeline</code> → Status = ACTIVE, More filters → Source = <b>Form web</b> (tiếng Anh: “Web form”; trước PR fe #435 hiện chữ thô WEB_FORM) → biểu tượng <b>Saved filters / Bộ lọc đã lưu</b> → <b>Save current view / Lưu bộ lọc hiện tại</b> → tên <code>QA view 1010</code> → tick “Set as default…” → lưu. Mở menu Pipeline lần nữa (URL trống). Rồi ⋯ → <b>Rename / Đổi tên</b> → <code>QA view 1010b</code>; đổi bộ lọc → ⋯ → <b>Overwrite with current view</b>; ⭐ bỏ mặc định; ⋯ → <b>Delete / Xoá</b> → xác nhận. Cuối cùng: Manager mở Saved filters.", "Lưu: toast “View saved” / “Đã lưu bộ lọc”, badge “Default / Mặc định”. Mở lại Pipeline từ menu: bộ lọc tự áp (KHÔNG có toast — chuỗi “View \"X\" applied” có trong file dịch nhưng không dùng). Rename / Overwrite: “View updated” / “Đã cập nhật bộ lọc”. Bỏ mặc định: “Default cleared”. Xoá: hộp “Delete this saved view? This cannot be undone.” → “View deleted” / “Đã xoá bộ lọc”. Manager: KHÔNG thấy view của recruiter (“Nothing saved yet — …”).", "<code>recruit.viet18.com/pipeline</code> → Status = ACTIVE, More filters → Source = <b>Web form</b> (before fe PR #435 it showed the raw code WEB_FORM) → the <b>Saved filters</b> icon → <b>Save current view</b> → name <code>QA view 1010</code> → tick “Set as default…” → save. Open Pipeline from the menu again (clean URL). Then ⋯ → <b>Rename</b> → <code>QA view 1010b</code>; change a filter → ⋯ → <b>Overwrite with current view</b>; ⭐ to clear default; ⋯ → <b>Delete</b> → confirm. Finally the Manager opens Saved filters.", "Save: toast “View saved”, badge “Default”. Reopening Pipeline from the menu: filters auto-apply (NO toast — “View \"X\" applied” exists in the messages but is unused). Rename / Overwrite: “View updated”. Clear default: “Default cleared”. Delete: “Delete this saved view? This cannot be undone.” → “View deleted”. Manager: does NOT see the recruiter's view (“Nothing saved yet — …”)."),
    S("AE2", "MGR", "Manager → Pipeline (dạng Table) → ô tìm <code>Tenaearch</code> → tick QA Tenaearchone + QA Tenaearchtwo → thanh dưới “2 selected” → <b>Archive…</b> → “Reason (optional)” = <code>QA bulk archive 10/10</code> → <b>Archive 2 rows</b>. Rồi đổi Status = ARCHIVED (hoặc tất cả) → tick lại QA Tenaearchone (đã archive) → Archive… → xác nhận. Mở hồ sơ QA Tenaearchone → Activity.", "Hộp “Archive 2 candidates” / “Archive 2 hồ sơ”. Toast “<b>2 candidates archived</b>” / “Đã archive 2 hồ sơ”; cả hai status Archived, biến khỏi Pipeline mặc định (chỉ ACTIVE). Lần 2: “1 row skipped — already in that state” / “1 dòng bỏ qua — đã ở trạng thái đó rồi”. Activity: “Archived (QA bulk archive 10/10)”. (Board không có thanh chọn hàng loạt.)", "Manager → Pipeline (Table view) → search <code>Tenaearch</code> → tick QA Tenaearchone + QA Tenaearchtwo → bottom bar “2 selected” → <b>Archive…</b> → “Reason (optional)” = <code>QA bulk archive 10/10</code> → <b>Archive 2 rows</b>. Then set Status = ARCHIVED (or all) → tick QA Tenaearchone again (already archived) → Archive… → confirm. Open QA Tenaearchone → Activity.", "Dialog “Archive 2 candidates”. Toast “<b>2 candidates archived</b>”; both Archived, gone from the default (ACTIVE) Pipeline. Second time: “1 row skipped — already in that state”. Activity: “Archived (QA bulk archive 10/10)”. (Board view has no bulk bar.)"),
    S("AE3", "REC", "Recruiter → Pipeline → ô tìm <code>Bnotmine</code> → tick QA Bnotmine (lead của Manager) → <b>Archive…</b> → <b>Archive 1 row</b>.", "Toast “<b>1 row did not complete: Missing permission CANDIDATE_TRANSFER — ask an admin for a recruiting grant</b>”; QA Bnotmine vẫn ACTIVE. Nếu bị archive thật → <b>Lỗi</b> + nhờ dev khôi phục.", "Recruiter → Pipeline → search <code>Bnotmine</code> → tick QA Bnotmine (the Manager's lead) → <b>Archive…</b> → <b>Archive 1 row</b>.", "Toast “<b>1 row did not complete: Missing permission CANDIDATE_TRANSFER — ask an admin for a recruiting grant</b>”; QA Bnotmine stays ACTIVE. If it really got archived → <b>Fail</b> + ask a dev to restore."),
    S("AE4", "REC", "Pipeline → bật <b>No owner yet / Chưa có người phụ trách</b> → tải lại trang → ⋯ trên một dòng → <b>Copy email</b>, rồi <b>Copy phone / Copy số điện thoại</b> → dán vào ô ghi chú. Trên một dòng CỦA MÌNH: bấm biểu tượng copy cạnh email. Đổi “Rows per page” = 25. Di chuột ~1 giây lên tab stage (vd S2).", "URL có <code>owner=none</code>, giữ sau khi tải lại; các dòng ghi “— unowned / — chưa ai”. Toast “Email copied” / “Đã copy email”, “Phone copied” / “Đã copy số điện thoại”, dán đúng. Dòng của mình: không toast, tooltip đổi thành “Copied / Đã copy”. URL có <code>pageSize=25</code>, chân trang “Page 1 of N · {tổng} total”. Tooltip tab: “S2 · reached N · dropped N · nurture N”.", "Pipeline → turn on <b>No owner yet</b> → reload → ⋯ on a row → <b>Copy email</b>, then <b>Copy phone</b> → paste into the note. On one of YOUR rows: click the copy icon next to the email. Set “Rows per page” = 25. Hover ~1 s over a stage tab (e.g. S2).", "URL has <code>owner=none</code>, kept after reload; rows read “— unowned”. Toasts “Email copied”, “Phone copied”, pastes match. Own row: no toast, the tooltip turns into “Copied”. URL has <code>pageSize=25</code>, footer “Page 1 of N · {total} total”. Tab tooltip: “S2 · reached N · dropped N · nurture N”."),
    S("AE5", "REC", "(a) QA Tenaeboard (đã claim + Log result Interested, CHƯA có offer) → Pipeline → <b>Board view / Dạng Kanban</b> → thẻ QA Tenaeboard → ⋯ → <b>Move to stage / Chuyển sang giai đoạn</b> → <b>Move to Joined</b>. Rồi ⋯ → chuyển tới Onboarding → rồi ⋯ → chuyển LÙI về Engaged. Mở hồ sơ. (b) Một LO của mình ĐÃ Send to onboarding (đường A6–A9: Log result → Interested → Yes, prepare offer → điền đủ 2 số để tự duyệt → Send to onboarding; stage tự nhảy Engaged → Onboarding) → Board → ⋯ → Chuyển sang giai đoạn → lùi về Engaged → mở hồ sơ. Cuối: bấm thu gọn một cột rỗng / đầy.", "Joined: thẻ bật về chỗ cũ, toast “<b>Joined gate: S6 requires a SIGNED offer with the fee PAID or WAIVED</b>” (chữ backend, tiếng Anh). Chuyển tiến: “Moved QA Tenaeboard to {stage}” / “Đã chuyển QA Tenaeboard sang {stage}”. (a) Chuyển lùi xong: stepper “↩ Moved back from Onboarding · {ngày}”, KHÔNG có khung “Not advancing automatically” (chưa có offer nên không gì tự đẩy tiếp — đúng thiết kế D185). (b) LO có offer đã gửi: stepper như trên VÀ khung “<b>Not advancing automatically</b>” / “Chưa tự chuyển giai đoạn” + “Moved back to Engaged by Bao Trinh on {ngày}. It moves on again after a new invite or signature.” (tên lấy từ email bao.trinh+recruiter → “Bao Trinh”) Cột thu gọn: “Show {tên cột} (n)” / “Mở cột {tên cột} (n)”.", "(a) QA Tenaeboard (claimed + Log result Interested, NO offer) → Pipeline → <b>Board view</b> → the card → ⋯ → <b>Move to stage</b> → <b>Move to Joined</b>. Then move to Onboarding → then move it BACK to Engaged. Open the profile. (b) A loan officer you own whose offer was sent to onboarding (A6–A9 route; the stage moves Engaged → Onboarding by itself) → Board → ⋯ → Move to stage → back to Engaged → open the profile. Finally fold a column.", "Joined: the card snaps back, toast “<b>Joined gate: S6 requires a SIGNED offer with the fee PAID or WAIVED</b>” (backend English). Forward: “Moved QA Tenaeboard to {stage}”. (a) After moving back: stepper “↩ Moved back from Onboarding · {date}”, NO “Not advancing automatically” box (no offer, nothing would move it forward — by design, D185). (b) Loan officer with a sent offer: same stepper line AND the box “<b>Not advancing automatically</b>” + “Moved back to Engaged by Bao Trinh on {date}. It moves on again after a new invite or signature.” (the name is derived from the email bao.trinh+recruiter → “Bao Trinh”) Folded column: “Show {column} (n)”."),
    S("AE6", "REC", "Hồ sơ QA Tenaelabel → chip <b>+ Label</b> ở đầu trang → gõ <code>QA label 1010</code> → <b>Add / Thêm</b>. Gõ tiếp một tên 41 ký tự <code>QA label 1010 abcdefghijklmnopqrstuvwxyz0</code> → Add. Pipeline → <b>More filters / Bộ lọc khác</b> → <b>Filter by label / Lọc theo label</b> = “QA label 1010 · 1”. Quay lại hồ sơ → × trên chip (cả hai chip nếu tên dài lỡ được nhận).", "Chip hiện ngay (không toast). Tên 41 ký tự: “A label name can be at most 40 characters (this one is 41)” (tiếng Anh cả khi giao diện Việt). Pipeline chỉ còn QA Tenaelabel, nút “Filters · 1” / “Bộ lọc · 1”, URL có <code>label=</code>. Bấm × → chip mất. (Label vẫn nằm trong danh mục — không có màn xoá danh mục.)", "QA Tenaelabel's profile → header chip <b>+ Label</b> → type <code>QA label 1010</code> → <b>Add</b>. Then a 41-character name <code>QA label 1010 abcdefghijklmnopqrstuvwxyz0</code> → Add. Pipeline → <b>More filters</b> → <b>Filter by label</b> = “QA label 1010 · 1”. Back on the profile → × on the chip (both chips if the long name was wrongly accepted).", "Chip appears at once (no toast). 41 characters: “A label name can be at most 40 characters (this one is 41)” (English even in the Vietnamese UI). Pipeline shows only QA Tenaelabel, button “Filters · 1”, URL has <code>label=</code>. × removes the chip. (The label stays in the catalog — there is no catalog screen.)"),
    SA("roleOfr", "AE7", "OFR", "Officer recruiter (chưa giữ LO nào) → <b>My work today</b>. Bấm <b>Claim the next N / Nhận N người tiếp theo</b>. (Thử nút <b>Browse the Cold list / Mở Kho COLD</b> trước khi bấm Claim.)", "Trước khi nhận: “<b>Nobody on your list yet</b>” / “Chưa có ai trong danh sách của bạn” + “Your queue is empty and {stock} candidates in the Cold list have no recruiter…”; N = 10 (batch mặc định). Browse → <code>/inbox/cold</code>. Claim: toast “<b>10 candidates are yours — your queue is ready</b>” (hoặc “… · {n} were claimed by someone else first”), các dòng hiện ra. Hết người trong kho: “Nothing left to hand over: …”. Không cần trả lại (staging).", "Officer recruiter (holds no LO yet) → <b>My work today</b>. Click <b>Claim the next N</b>. (Try <b>Browse the Cold list</b> before claiming.)", "Before: “<b>Nobody on your list yet</b>” + “Your queue is empty and {stock} candidates in the Cold list have no recruiter…”; N = 10 (default batch). Browse → <code>/inbox/cold</code>. Claim: toast “<b>10 candidates are yours — your queue is ready</b>” (or “… · {n} were claimed by someone else first”), rows appear. Empty pool: “Nothing left to hand over: …”. No restore needed (staging)."),
    S("AE8", "REC", "Hồ sơ QA Tenaelabel → tab Activity (<code>?section=activity</code>) → khối “Contact history / Lịch sử liên lạc” → chip <b>Messages / Tin nhắn</b>, rồi <b>System &amp; stage / Hệ thống &amp; stage</b>, rồi <b>All / Tất cả</b>.", "Messages: chỉ CALL / SMS / EMAIL / NOTE / MEETING. System &amp; stage: chỉ dòng hệ thống + chuyển stage. Bộ lọc không có dòng nào: “Nothing matches this filter.” / “Không có gì khớp với bộ lọc này.”", "QA Tenaelabel → Activity tab (<code>?section=activity</code>) → “Contact history” → chip <b>Messages</b>, then <b>System &amp; stage</b>, then <b>All</b>.", "Messages: only CALL / SMS / EMAIL / NOTE / MEETING. System &amp; stage: only system rows + stage moves. A filter with no rows: “Nothing matches this filter.”"),
    S("AE9", "REC", "QA Tenaelabel → Activity → <b>Add follow-up / Thêm follow-up</b> → Kind = Call → ngày hôm nay, giờ đã qua → Save; sửa thành ngày mai 10:00 → <b>Save follow-up</b>. Mở lại follow-up → đổi giờ 11:00 → Save. Bấm <b>Clear / Xong</b>. Rồi manhadmin (không phải chủ) mở cùng hồ sơ.", "Giờ đã qua: “That moment has already passed. Pick a time still to come.” Lưu: “Follow-up added” / “Đã thêm follow-up”; sửa: “Follow-up updated”; Clear: “Follow-up cleared” / “Đã đánh dấu follow-up xong” → nằm ở “Earlier follow-ups / Follow-up trước đó”. manhadmin: “Follow-ups are visible to the owner or a manager.”", "QA Tenaelabel → Activity → <b>Add follow-up</b> → Kind = Call → today with a past time → Save; change to tomorrow 10:00 → <b>Save follow-up</b>. Reopen → 11:00 → Save. Click <b>Clear</b>. Then manhadmin (not the owner) opens the same profile.", "Past time: “That moment has already passed. Pick a time still to come.” Save: “Follow-up added”; edit: “Follow-up updated”; Clear: “Follow-up cleared” → listed under “Earlier follow-ups”. manhadmin: “Follow-ups are visible to the owner or a manager.”"),
    S("AE10", "REC", "QA Tenaelabel → Profile → <b>Legal name / Tên pháp lý</b> → <b>Edit / Sửa</b> → first <code>1Anna</code> → Confirm; rồi first <code>Anna-Marie</code>, last <code>O'Neil</code> → <b>Confirm / Xác nhận</b>. TRẢ LẠI: Edit → <code>QA</code> / <code>Tenaelabel</code> → Confirm.", "“1Anna”: “Only letters, spaces, apostrophes, periods and hyphens are allowed, starting with a letter”. Anna-Marie / O'Neil: toast “Legal name confirmed” / “Đã xác nhận tên pháp lý”. Trả lại xong tên như cũ.", "QA Tenaelabel → Profile → <b>Legal name</b> → <b>Edit</b> → first <code>1Anna</code> → Confirm; then first <code>Anna-Marie</code>, last <code>O'Neil</code> → <b>Confirm</b>. RESTORE: Edit → <code>QA</code> / <code>Tenaelabel</code> → Confirm.", "“1Anna”: “Only letters, spaces, apostrophes, periods and hyphens are allowed, starting with a letter”. Anna-Marie / O'Neil: toast “Legal name confirmed”. After the restore the name is back."),
    S("AE11", "REC", "QA Tenaelabel → Profile → <b>Edit</b> → tab <b>Mailing / Địa chỉ</b>: <code>456 QA Ave</code>, <code>Austin</code>, State Texas, ZIP <code>73301</code> → Save. Mở lại → <b>Identity</b> → Preferred languages = Vietnamese + Spanish → Save. Mở lại → <b>Licensing</b> → Loan officer type = Independent — 1099, Employment type = Full time — W-2 → Save. Bấm <b>Cancel</b>. Mở tab <b>History / Lịch sử</b>.", "Hai lần lưu đầu: “Profile updated.” / “Đã cập nhật hồ sơ.”; Overview hiện địa chỉ mới, ngôn ngữ mới. Licensing: lỗi dưới Employment type “<b>Independent goes with Contract, and Contract only with Independent.</b>” / “Independent đi với Hợp đồng, và Hợp đồng chỉ đi với Independent.”, không lưu. Tab History = “Lịch sử liên lạc” (gọi, SMS, email, chuyển stage): KHÔNG có hai lần sửa hồ sơ — đúng thiết kế. Sửa địa chỉ/ngôn ngữ được ghi lại nhưng chưa màn nào hiện; chỉ sửa Loans since / Closed units hiện ở /audit của Manager → “Sửa số loan”.", "QA Tenaelabel → Profile → <b>Edit</b> → <b>Mailing</b> tab: <code>456 QA Ave</code>, <code>Austin</code>, State Texas, ZIP <code>73301</code> → Save. Reopen → <b>Identity</b> → Preferred languages = Vietnamese + Spanish → Save. Reopen → <b>Licensing</b> → Loan officer type = Independent — 1099, Employment type = Full time — W-2 → Save. Click <b>Cancel</b>. Open the <b>History</b> tab.", "First two saves: “Profile updated.”; Overview shows the new address and languages. Licensing: error under Employment type “<b>Independent goes with Contract, and Contract only with Independent.</b>”, nothing saved. History = “Contact history” (calls, SMS, email, stage moves): the two profile edits are NOT listed — by design. Address/language edits are recorded but no screen lists them; only Loans since / Closed units edits show on Manager /audit → “Production number edits”."),
    S("AE12", "MGR", "Manager → hồ sơ QA Tenaelabel (LO đến từ MOSO) → menu trái <b>Sync / Đồng bộ</b> (<code>?section=sync</code>). Bấm <b>Load more / Xem thêm</b> nếu có.", "Chip “MOSO link / Liên kết MOSO”; “MOSO feed last event: …”; “Packs writeback ON”; bảng MOSO events (Received / Processed / Failed / Skipped); “Not applied / Chưa áp dụng” (hoặc “Nothing was left unreconciled.”); “Writebacks to MOSO / Ghi ngược về MOSO”; “Offer ledger / Sổ ghi đề nghị”. (Recruiter không có mục này — P3.)", "Manager → QA Tenaelabel's profile (an LO from MOSO) → left menu <b>Sync</b> (<code>?section=sync</code>). Click <b>Load more</b> if shown.", "Chip “MOSO link”; “MOSO feed last event: …”; “Packs writeback ON”; MOSO events (Received / Processed / Failed / Skipped); “Not applied” (or “Nothing was left unreconciled.”); “Writebacks to MOSO”; “Offer ledger”. (Recruiters have no such section — P3.)"),
    S("AE13", "REC", "<b>Cold list / Kho COLD</b> → “50 / page” đổi thành <b>25 / page</b> → bấm số <b>2</b> trên thanh số trang (không có nút “Next”) → tải lại trang (KHÔNG có nút Refresh).", "URL có <code>pageSize=25</code> và <code>page=2</code>, giữ sau khi tải lại; chân trang “26–50 of {N} unowned candidates” / “26–50 / {N} người vô chủ”.", "<b>Cold list</b> → “50 / page” to <b>25 / page</b> → click page <b>2</b> in the numbered pager (there is no “Next” button) → reload the browser (there is NO Refresh button).", "URL has <code>pageSize=25</code> and <code>page=2</code>, kept after reload; footer “26–50 of {N} unowned candidates”."),
    S("AE14", "REC", "QA Tenaestop → Log result → <b>Not interested</b> → “Why?” = <b>Asked to stop contact / Yêu cầu ngừng liên hệ</b> → <b>Archive candidate</b>. Rồi trên hồ sơ thử bấm Email / Call.", "Toast “Archived” / “Đã lưu trữ”. Lý do chỉ được lưu dạng chữ: KHÔNG có dải “On the do-not-contact list.”, nút liên hệ vẫn bấm được. Ghi lại — câu hỏi thiết kế cho Bao (có nên tự đưa vào danh sách không liên hệ không), không phải lỗi màn hình.", "QA Tenaestop → Log result → <b>Not interested</b> → “Why?” = <b>Asked to stop contact</b> → <b>Archive candidate</b>. Then try Email / Call on the profile.", "Toast “Archived”. The reason is stored as text only: NO “On the do-not-contact list.” strip, contact buttons still work. Record it — a design question for Bao (should it add a do-not-contact entry?), not a screen bug.", { vi: "câu hỏi thiết kế: “Asked to stop contact” không tạo chặn liên hệ", en: "design question: “Asked to stop contact” creates no contact block" }),
    S("AE15", "RECSMS", "Chuẩn bị: Share chỉ bật khi LO có ít nhất 1 đồng nghiệp — Overview của LO đó → thêm QA Test Manager làm colleague (xoá lại ở cuối bước). manhadmin → Conversations → TRINH VU TRONG BAO → <b>Open</b> → rê chuột lên một tin SMS → <b>Pin / Ghim</b>; rồi <b>Unpin</b>; <b>Mark important / Đánh dấu quan trọng</b>; <b>Share via email / Chia sẻ qua email</b> → hộp “Share with team” → <b>Share</b>.", "Pin: “Pinned. Find it under the pin icon in the header.” / “Đã ghim. Xem lại ở biểu tượng ghim trên đầu trang.”; Unpin: “Removed from pinned.”; Important: “Marked important.”; Share: “Shared with the team.” / “Đã chia sẻ với nhóm.” (Share chỉ có trên tin SMS / ghi chú, không có trên email.)", "Prep: Share is enabled only when the loan officer has at least one colleague — that loan officer's Overview → add QA Test Manager as a colleague (remove at the end). manhadmin → Conversations → TRINH VU TRONG BAO → <b>Open</b> → hover an SMS → <b>Pin</b>; then <b>Unpin</b>; <b>Mark important</b>; <b>Share via email</b> → “Share with team” → <b>Share</b>.", "Pin: “Pinned. Find it under the pin icon in the header.”; Unpin: “Removed from pinned.”; Important: “Marked important.”; Share: “Shared with the team.” (Share is only on SMS / notes, not on emails.)"),
    S("AE16", "REC", "Recruiter → My work today → <b>Focus mode</b> → một LO có follow-up → <b>Remind later / Nhắc lại sau</b> → <b>Tomorrow 9:00am / Ngày mai 9:00am</b>. Mở hồ sơ LO xem giờ follow-up. Ghi ngày giờ VN lúc bấm.", "Toast “Follow-up rescheduled” / “Đã dời lịch follow-up”. Follow-up nằm ở <b>9:00 sáng giờ Los Angeles của ngày làm việc kế tiếp</b> (bỏ qua thứ Bảy, Chủ nhật, ngày lễ) — PDT = 23:00 VN cùng ngày đó. Bản đang chạy (10/10) còn dùng giờ máy tính → nếu ra 9:00 giờ VN hoặc rơi vào thứ Bảy thì đánh <b>Lỗi</b> “B2 (chờ bản sửa)”. “This evening 5:00pm” bị tắt sau 17:00 theo giờ máy tính.", "Recruiter → My work today → <b>Focus mode</b> → an LO with a follow-up → <b>Remind later</b> → <b>Tomorrow 9:00am</b>. Open the LO profile to read the follow-up time. Note the VN time you clicked.", "Toast “Follow-up rescheduled”. The follow-up lands at <b>9:00 AM Los Angeles on the next business day</b> (skipping Sat, Sun, holidays) — in PDT that is 23:00 VN the same date. The build live on 10/10 still uses the computer clock → 9:00 VN time or a Saturday = <b>Fail</b> “B2 (fix pending)”. “This evening 5:00pm” is disabled after 17:00 computer time.", { vi: "B2: sẽ sửa theo giờ làm việc Pacific (Bao 10/10)", en: "B2: to be fixed to Pacific business time (Bao 10/10)" })
  ] });

// ================= AF · onboarding & hand-offs never tested =================
CASES.push({ id: "AF", group: G_NEW, short: { vi: "Onboarding & chuyển giao: phần chưa test", en: "Onboarding & hand-offs: untested parts" },
  title: { vi: "Onboarding và My hand-offs: nhắc onboarding, đổi loại LO sau khi có hợp đồng, checklist trên hồ sơ, Team queue, Google, mẫu checklist", en: "Onboarding and My hand-offs: remind onboarding, changing the LO type after the agreement, profile checklist, Team queue, Google, checklist templates" },
  goal: { vi: "Các nút hằng ngày của recruiter / onboarding chưa ai bấm, và hộp cảnh báo khi đổi loại LO sau khi MOSO đã tạo hợp đồng.", en: "Daily recruiter / onboarding buttons nobody has pressed, and the dialogs when the LO type changes after MOSO built the agreement." },
  acc: ["rec", "onb", "onbG", "recSms"], res: ["register", "cron", "google"], lock: true,
  loNote: { vi: "NAF1 đi như A1–A14 (tới 1-1 Done, CHƯA trả phí / ký). NAF2 chỉ cần claim. QA Bfour / QA Bfive: lời mời gửi 06/10, 1-1 chưa xong (đọc DB 10/10). HO1 = QA Handoffnmls (đã ký, Joined).", en: "NAF1 goes through A1–A14 (to 1-1 Done, NOT paid / signed). NAF2 only needs a claim. QA Bfour / QA Bfive: invited 06/10, 1-1 not done (DB 10/10). HO1 = QA Handoffnmls (signed, Joined)." },
  steps: [
    S("AF1", "REC", "Menu <b>My hand-offs / Chuyển giao của tôi</b> → “Requested / Ngày yêu cầu” → <b>Custom… / Tùy chọn…</b> → chỉ chọn From = 01/10/2026; rồi To = 10/10/2026. Thử chọn To trước From. Tải lại trang. Đổi Rows/page = 50.", "Mới chọn một ngày: “Pick both dates to apply the range.” / “Chọn cả hai ngày để áp dụng.” Không chọn được To trước From (lịch khoá ngày). Đủ hai ngày: URL <code>range=custom&amp;from=2026-10-01&amp;to=2026-10-10</code>, giữ sau khi tải lại. Gõ tay To trước From thì gợi ý vẫn hiện và không áp dụng gì. (Nhãn khoảng ngày không ghi năm — B5, chỉ thẩm mỹ.)", "Menu <b>My hand-offs</b> → “Requested” → <b>Custom…</b> → pick only From = 10/01/2026; then To = 10/10/2026. Try a To before From. Reload. Set Rows/page = 50.", "One date only: “Pick both dates to apply the range.” A To before From cannot be picked (calendar limits). Both: URL <code>range=custom&amp;from=2026-10-01&amp;to=2026-10-10</code>, kept after reload. Typing a To before From by hand keeps the hint and applies nothing. (The range label has no year — B5, cosmetic.)"),
    S("AF2", "REC", "My hand-offs → Requested = All time → tìm <code>Bfour</code> (hoặc <code>Bfive</code>) → dòng “1-1 pending” → <b>Remind onboarding / Nhắc onboarding</b> → “Note for {name} (optional)” = <code>QA AF2</code> → <b>Send reminder / Gửi lời nhắc</b>. Bấm lại lần nữa. Rồi đăng nhập <code>bao.trinh+onb-test@loanfactory.com</code> → chuông.", "Nút chỉ có khi dòng trễ (&gt;3 ngày) và đã có specialist; không có → Bỏ. Toast “<b>Reminded ONB Test Specialist LF about QA Bfour</b>” / “Đã nhắc … về QA Bfour”. Lần 2: nút mờ “Reminded · again {giờ}” / “Đã nhắc · nhắc lại {giờ}” (chờ 60 phút). Chuông onb-test: “<b>QA Test Recruiter asked you to book the 1-1 with QA Bfour</b>” / “… nhờ bạn đặt lịch 1-1 với QA Bfour”.", "My hand-offs → Requested = All time → search <code>Bfour</code> (or <code>Bfive</code>) → the “1-1 pending” row → <b>Remind onboarding</b> → “Note for {name} (optional)” = <code>QA AF2</code> → <b>Send reminder</b>. Click it again. Then sign in as <code>bao.trinh+onb-test@loanfactory.com</code> → bell.", "The button only shows when the row is late (&gt;3 days) and has a specialist; absent → Skip. Toast “<b>Reminded ONB Test Specialist LF about QA Bfour</b>”. Second time: disabled “Reminded · again {time}” (60-min cooldown). onb-test bell: “<b>QA Test Recruiter asked you to book the 1-1 with QA Bfour</b>”."),
    S("AF3", "ONB", "Onboarding → <b>Team queue / Hàng đợi nhóm</b> → bấm lần lượt thẻ <b>Overdue / Quá hạn</b>, <b>Due today / Hạn hôm nay</b>, <b>Blocked / Bị chặn</b>, <b>Open / Đang mở</b>. Rồi đổi phòng sang <b>Accounting / Kế toán</b>.", "Mỗi thẻ lọc danh sách, URL <code>f=overdue|today|blocked</code>, giữ sau khi tải lại. Bộ đổi phòng CHỈ có Onboarding + Accounting (không có HR / Licensing). Sang Accounting (khi có dòng): “You can see Accounting's work, but only Accounting can close it.” / “Bạn xem được việc của Kế toán, nhưng chỉ Kế toán mới đóng được.”", "Onboarding → <b>Team queue</b> → click the cards <b>Overdue</b>, <b>Due today</b>, <b>Blocked</b>, <b>Open</b> in turn. Then switch the department to <b>Accounting</b>.", "Each card filters the list, URL <code>f=overdue|today|blocked</code>, kept after reload. The switcher has ONLY Onboarding + Accounting (no HR / Licensing). On Accounting (when it has rows): “You can see Accounting's work, but only Accounting can close it.”"),
    S("AF4", "ONBG", "Sau J6 (1-1 có Meet): Team queue → dòng QA Anewe → <b>Copy Meet link / Copy link Meet</b> → dán vào ghi chú. Sau giờ kết thúc buổi họp, mở lại Team queue.", "Toast “Meet link copied” / “Đã copy link Meet”, dán ra <code>meet.google.com/…</code>. Sau giờ họp: “Meeting time has passed. Did it happen?” / “Đã qua giờ họp. Buổi họp có diễn ra không?”", "After J6 (1-1 with Meet): Team queue → the QA Anewe row → <b>Copy Meet link</b> → paste into the note. After the meeting's end time, reopen Team queue.", "Toast “Meet link copied”, pastes <code>meet.google.com/…</code>. After the slot: “Meeting time has passed. Did it happen?”"),
    S("AF5", "ONBG", "<b>Điểm danh Meet</b> (⚑ chỉ staging, MEET_ATTENDANCE): buổi 1-1 của J6 — anh vào Meet bằng bao.trinh@; LO tham gia (ở ≥10 phút) bằng cửa sổ ẩn danh “Ask to join” tên <code>QA Anewe</code> (hoặc KHÔNG cho ai vào, để thử vắng mặt). Sau giờ kết thúc + 15 phút + một tick 5 phút → chuông.", "Một trong các chuông: “QA Anewe was in your 1-1 on Meet for {N} min. Mark it done?” / “QA Anewe đã ở trong buổi 1-1 trên Meet {N} phút. Đánh dấu đã xong?”; khách ẩn danh: “Someone joined your 1-1 with QA Anewe on Meet, but Recruit could not tell if it was QA Anewe…”; LO ở ít hơn 10 phút: “QA Anewe was in your 1-1 on Meet for only {N} min. Check before you mark it done.”; không ai vào: “QA Anewe did not join your 1-1 on Meet. It may be a no-show.”; không có cuộc Meet: “No Meet call was found for your 1-1 with QA Anewe. Check whether it took place.” Ghi rõ biến thể nào. (10 phút tính theo thời gian của LO trong phòng.)", "<b>Meet attendance</b> (⚑ staging only, MEET_ATTENDANCE): the J6 1-1 — you join Meet as bao.trinh@; the LO joins (stays ≥10 min) from incognito “Ask to join” as <code>QA Anewe</code> (or let NOBODY join, to try the no-show). After the end time + 15 min + one 5-min tick → bell.", "One of: “QA Anewe was in your 1-1 on Meet for {N} min. Mark it done?”; anonymous guest: “Someone joined your 1-1 with QA Anewe on Meet, but Recruit could not tell if it was QA Anewe…”; LO under 10 min: “QA Anewe was in your 1-1 on Meet for only {N} min. Check before you mark it done.”; nobody: “QA Anewe did not join your 1-1 on Meet. It may be a no-show.”; no Meet call: “No Meet call was found for your 1-1 with QA Anewe. Check whether it took place.” Note which variant. (The 10 minutes are the LO's time in the room.)"),
    S("AF6", "ONB", "Ô tìm <code>Handoffnmls</code> → Overview → <b>Onboarding checklist</b> → nhóm Onboarding, một việc chưa xong (không phải 1-1) → <b>Block / Chặn</b> → lý do <code>QA AF6 wait docs</code> → Block → <b>Unblock / Bỏ chặn</b> → <b>N/A / Không áp dụng</b> → lý do → <b>Mark N/A</b> → <b>Reopen / Mở lại</b>. Nhìn việc 1-1. Rồi Recruiter mở cùng hồ sơ.", "Mỗi bước: toast “Updated “{tên việc}”” / “Đã cập nhật “{tên việc}””; cuối cùng việc về trạng thái mở như ban đầu. Việc 1-1: “Marked done from the Onboarding queue. It can't be reopened from this panel.” (hoặc nếu chưa xong: Done mờ “Done needs the meeting date — mark this one from the Onboarding queue.”). Recruiter: không nút, nhóm ghi “Onboarding moves these” / “Onboarding sửa”; HR/Licensing “… is tracked outside this app”.", "Search <code>Handoffnmls</code> → Overview → <b>Onboarding checklist</b> → Onboarding group, an open item (not the 1-1) → <b>Block</b> → reason <code>QA AF6 wait docs</code> → Block → <b>Unblock</b> → <b>N/A</b> → reason → <b>Mark N/A</b> → <b>Reopen</b>. Look at the 1-1 item. Then the Recruiter opens the same profile.", "Each step: toast “Updated “{item}””; at the end the item is open again as before. 1-1 item: “Marked done from the Onboarding queue. It can't be reopened from this panel.” (or, if not done: Done disabled “Done needs the meeting date — mark this one from the Onboarding queue.”). Recruiter: no buttons, group says “Onboarding moves these”; HR/Licensing “… is tracked outside this app”."),
    S("AF7", "ONB", "⚠ Staging chỉ gửi hợp đồng tới email trong allowlist: đăng ký LO MỚI bằng <code>bao.trinh+agree4@loanfactory.com</code> (agree4–agree9 thêm ở PR be #619; agree1/agree2 đã dùng 10/10, agree3 giữ cho AF9) theo ★ mục 5, rồi đưa tới 1-1 Done W-2 (A1–A14, chưa trả phí; nếu không phải specialist được giao: Done… → “Do it anyway”). Đợi 5 phút (MOSO tạo hợp đồng). Onboarding → hồ sơ → Profile → <b>Edit</b> → <b>Licensing / Giấy phép</b> → Loan officer type = <b>Independent — 1099</b>, Employment type = <b>Contract — 1099</b> → đọc cảnh báo dưới ô → <b>Save</b> → hộp hiện ra → bấm <b>Send to QA</b>.", "Cảnh báo: “MOSO already built the … agreement. After you save, Recruit checks with MOSO and tells you what to do next.” / “MOSO đã tạo hợp đồng … Sau khi bạn lưu, Recruit sẽ kiểm tra với MOSO…”. Toast “Profile updated.”. Hộp “<b>Send the updated agreement to QA Tenaftype?</b>” + “You changed the profile. MOSO's agreement no longer matches it.”, nút “Later / Để sau” và “Send to QA / Gửi cho QA”. Email LO không trong allowlist → “This environment only sends the agreement to approved test recipients.” → bấm Later. ⚑ chỉ staging (AGREEMENT_SEND; prod xem AG5).", "⚠ Staging only sends the agreement to allowlisted emails: register a NEW loan officer with <code>bao.trinh+agree4@loanfactory.com</code> (agree4–agree9 added in be PR #619; agree1/agree2 used 10/10, agree3 kept for AF9) per ★ item 5, then take it to 1-1 Done W-2 (A1–A14, unpaid; if you are not the assigned specialist: Done… → “Do it anyway”). Wait 5 min (MOSO builds the agreement). Onboarding → profile → Profile → <b>Edit</b> → <b>Licensing</b> → Loan officer type = <b>Independent — 1099</b>, Employment type = <b>Contract — 1099</b> → read the warning → <b>Save</b> → a dialog opens → click <b>Send to QA</b>.", "Warning: “MOSO already built the … agreement. After you save, Recruit checks with MOSO and tells you what to do next.” Toast “Profile updated.”. Dialog “<b>Send the updated agreement to QA Tenaftype?</b>” + “You changed the profile. MOSO's agreement no longer matches it.”, buttons “Later” and “Send to QA”. The LO email is not allowlisted → “This environment only sends the agreement to approved test recipients.” → click Later. ⚑ staging only (AGREEMENT_SEND; production: AG5)."),
    S("AF8", "ONB", "Tiếp AF7: Edit → Licensing → Loan officer type = <b>Corporate — W-2</b> (Employment type = Full time — W-2) → Save. TRẢ LẠI: Edit → Outside — W-2 + Full time — W-2 → Save → nếu có hộp thì Later / Close.", "Hộp “<b>No agreement for a Corporate loan officer</b>” / “Loan officer Corporate không có hợp đồng này” + “You changed Loan officer type to …”, cảnh báo “… Neither Recruit nor MOSO can cancel it yet. Don't re-generate it, and tell the loan officer not to sign it.”, chỉ nút Close. Trả lại xong loại về Outside — W-2.", "Continue AF7: Edit → Licensing → Loan officer type = <b>Corporate — W-2</b> (Employment type = Full time — W-2) → Save. RESTORE: Edit → Outside — W-2 + Full time — W-2 → Save → Later / Close if a dialog shows.", "Dialog “<b>No agreement for a Corporate loan officer</b>” + “You changed Loan officer type to …”, warning “… Neither Recruit nor MOSO can cancel it yet. Don't re-generate it, and tell the loan officer not to sign it.”, Close only. After the restore the type is Outside — W-2 again."),
    S("AF9", "ONB", "LO có email <code>bao.trinh+agree3@loanfactory.com</code> đã KÝ hợp đồng trên Inkless (link ký về hộp thư bao.trinh — Bao ký tay; email ngoài allowlist như QA Handoffnmls sẽ KHÔNG ra hộp này trên staging) → Profile → Edit → Licensing → ghi lại loại + hình thức hiện tại → đổi sang Independent — 1099 + Contract — 1099 → Save. TRẢ LẠI ngay: đổi về đúng giá trị cũ → Save → Close.", "Hộp “<b>The agreement no longer matches</b>” / “Hợp đồng không còn khớp” + “You changed the profile, but the loan officer already signed.” + “<b>Recruit can't send a new agreement</b>” / “Recruit không gửi được hợp đồng mới”, chỉ nút Close. Trả lại xong về như cũ (lưu ý: staging ghi ngược hồ sơ sang MOSO, nên phải trả lại).", "A loan officer with email <code>bao.trinh+agree3@loanfactory.com</code> whose agreement is SIGNED in Inkless (signing link goes to Bao's inbox — Bao signs by hand; an email outside the allowlist such as QA Handoffnmls will NOT show this dialog on staging) → Profile → Edit → Licensing → note the current type + employment → change to Independent — 1099 + Contract — 1099 → Save. RESTORE at once: set the old values → Save → Close.", "Dialog “<b>The agreement no longer matches</b>” + “You changed the profile, but the loan officer already signed.” + “<b>Recruit can't send a new agreement</b>”, Close only. After the restore it is as before (staging writes profile edits back to MOSO, so do restore)."),
    S("AF10", "REC", "NAF2 · QA Tenafclock: Hot leads → Claim (CHƯA gọi). My work today → ⋯ trên dòng → <b>Hand off to a colleague… / Chuyển cho đồng nghiệp…</b> → chọn Manh Admin → lý do <b>Other / Khác</b> + ghi chú <code>QA AF10</code> → gửi.", "Trong hộp: “<b>QA Tenafclock is a hot lead on a contact clock. After the hand-off the clock starts again for Manh.</b>” / “… Sau khi chuyển, đồng hồ bắt đầu lại cho Manh.” (chỉ hiện khi mở từ My work today; dùng tên gọi). Ghi chú không bắt buộc. Gửi xong: chủ = Manh Admin.", "NAF2 · QA Tenafclock: Hot leads → Claim (do NOT call). My work today → ⋯ on the row → <b>Hand off to a colleague…</b> → Manh Admin → reason <b>Other</b> + note <code>QA AF10</code> → send.", "In the dialog: “<b>QA Tenafclock is a hot lead on a contact clock. After the hand-off the clock starts again for Manh.</b>” (only when opened from My work today; first name). The note is optional. After sending: owner = Manh Admin."),
    S("AF11", "ONB", "Onboarding → <b>Checklist templates / Mẫu checklist</b> (phòng Onboarding) → <b>Add item / Thêm mục</b> → Title <code>QA item 1010</code>, Due in (days) <code>3</code>, Created when = “Created when the offer is sent / Tạo khi offer được gửi”, Code để gợi ý → lưu. Add item lần nữa cùng Code. TRẢ LẠI NGAY: công tắc Active của QA item 1010 → “Turn off …?” → <b>Turn off / Tắt</b>.", "Toast “<b>Added \"QA item 1010\". Candidates who reach its step from now on get it.</b>” Trùng mã: “Another item already uses this code. Pick a different one.” Tắt: “Saved — \"QA item 1010\" is now off.” (Không có nút xoá — mục tắt vẫn còn trong danh sách.) Làm nhanh: trong lúc bật, mọi offer gửi đi đều nhận việc này.", "Onboarding → <b>Checklist templates</b> (Onboarding) → <b>Add item</b> → Title <code>QA item 1010</code>, Due in (days) <code>3</code>, Created when = “Created when the offer is sent”, Code as suggested → save. Add item again with the same Code. RESTORE AT ONCE: QA item 1010's Active switch → “Turn off …?” → <b>Turn off</b>.", "Toast “<b>Added \"QA item 1010\". Candidates who reach its step from now on get it.</b>” Same code: “Another item already uses this code. Pick a different one.” Off: “Saved — \"QA item 1010\" is now off.” (No delete button — the item stays listed, switched off.) Be quick: while it is on, every offer sent gets this item."),
    S("AF12", "ONBG", "Làm SAU case J. bao.trinh@ → <b>Connections / Kết nối</b> (<code>/settings/connections</code>) → <b>Disconnect / Ngắt kết nối</b> → xác nhận. <b>Connect Google</b> → chọn một tài khoản @gmail.com. Connect lần nữa → đúng bao.trinh@loanfactory.com → ở màn đồng ý của Google bấm Cancel. TRẢ LẠI: Connect đúng tài khoản → cho phép → <b>Grant Meet access</b>.", "Hộp “Disconnect Google?” → toast “Google disconnected.” / “Đã ngắt kết nối Google.” Gmail: “Only a loanfactory.com Google account can be connected. Choose your work account and try again.” Cancel: “You did not allow access at Google, so nothing was connected.” Cuối cùng trạng thái đã nối + có quyền Meet như trước.", "Do AFTER case J. bao.trinh@ → <b>Connections</b> (<code>/settings/connections</code>) → <b>Disconnect</b> → confirm. <b>Connect Google</b> → pick an @gmail.com account. Connect again → the right bao.trinh@loanfactory.com → Cancel on Google's consent screen. RESTORE: Connect the right account → allow → <b>Grant Meet access</b>.", "“Disconnect Google?” → toast “Google disconnected.” Gmail: “Only a loanfactory.com Google account can be connected. Choose your work account and try again.” Cancel: “You did not allow access at Google, so nothing was connected.” At the end it is connected with Meet access as before."),
    S("AF13", "ONB", "Team queue: chỉ khi có dòng ghi “<b>Not sent / Chưa gửi được</b>” (1-1 Done mà MOSO từ chối) → <b>Open profile</b> sửa trường thiếu → quay lại → <b>Send again / Gửi lại</b>. Không có dòng nào → Bỏ (không tự gây lỗi được từ giao diện).", "Dòng ghi “MOSO did not accept it — missing: {fields}. Fix it, then send again.” Sau khi sửa: toast “Sent again” / “Đã gửi lại”, ≤5 phút hết chữ Not sent.", "Team queue: only if a row says “<b>Not sent</b>” (1-1 Done that MOSO refused) → <b>Open profile</b>, fix the missing field → back → <b>Send again</b>. No such row → Skip (the UI cannot cause the failure).", "The row says “MOSO did not accept it — missing: {fields}. Fix it, then send again.” After the fix: toast “Sent again”, within ≤5 min “Not sent” is gone.")
  ] });

// ================= AH · admin screens + header + sign-in =================
CASES.push({ id: "AH", group: G_NEW, short: { vi: "Admin, header, đăng nhập: phần chưa test", en: "Admin, header, sign-in: untested parts" },
  title: { vi: "Settings (ngày nghỉ, đồng hồ liên hệ, hạn theo nguồn…), Templates, Audit, Permissions, Program members, header, đăng nhập", en: "Settings (holidays, contact clock, deadline by source…), Templates, Audit, Permissions, Program members, header, sign-in" },
  goal: { vi: "Các mục cấu hình có thể dừng MỌI đồng hồ SLA phải đổi được VÀ trả lại được; các màn admin còn lại làm đúng.", en: "Settings that can pause EVERY SLA clock must be changeable AND restorable; the other admin screens behave." },
  acc: ["admin", "mgr", "rec"], res: ["settings"], lock: true,
  warn: { vi: "Settings là CHUNG. Bấm “Tôi đang đổi /settings”, chụp giá trị đang hiện trước khi đổi, trả lại ĐÚNG giá trị đó ngay trong cùng bước, rồi nhả khoá.", en: "Settings are SHARED. Press “I'm changing /settings”, screenshot the value before changing, restore EXACTLY that value in the same step, then release." },
  steps: [
    S("AH1", "ADMIN", "<code>/settings</code> → <b>Holidays / Ngày nghỉ lễ</b> → “Company extra days off” → “Add a date” = <code>2026-12-31</code> → <b>Save / Lưu</b>. Xem “Upcoming days off” và dòng Independence Day / Juneteenth. TRẢ LẠI: × trên chip 2026-12-31 → Save.", "Toast “Setting saved” / “Đã lưu cấu hình”; “Upcoming days off” có 2026-12-31 “Company day off” / “Ngày nghỉ của công ty”. Independence Day: “next: 2027-07-05 (observed for 2027-07-04)” / “lần tới: … (nghỉ bù cho …)”. Trả lại: chip mất, danh sách như cũ (đầu: 2026-10-12, 11-11, 11-26, 12-25, 2027-01-01).", "<code>/settings</code> → <b>Holidays</b> → “Company extra days off” → “Add a date” = <code>2026-12-31</code> → <b>Save</b>. Read “Upcoming days off” and the Independence Day / Juneteenth rows. RESTORE: × on the 2026-12-31 chip → Save.", "Toast “Setting saved”; “Upcoming days off” lists 2026-12-31 “Company day off”. Independence Day: “next: 2027-07-05 (observed for 2027-07-04)”. After the restore the chip is gone, the list is as before (first: 2026-10-12, 11-11, 11-26, 12-25, 2027-01-01)."),
    S("AH2", "ADMIN", "<code>/settings</code> → “<b>Contact clock starts at / Đồng hồ liên hệ bắt đầu từ</b>” → CHỤP giá trị hiện tại → đặt ngày mai 08:00 → Save. TRẢ LẠI NGAY đúng giá trị đã chụp (ô chỉ tới phút — trả lại đúng tới phút) → Save.", "Sau khi lưu: “<b>The contact SLA is paused until {ngày giờ} — no claim or transfer starts a clock before then.</b>” / “SLA liên hệ đang tạm dừng tới …”. Trả lại: dòng tạm dừng biến mất, “Changed by Chau Chau on {ngày}”.", "<code>/settings</code> → “<b>Contact clock starts at</b>” → SCREENSHOT the current value → set tomorrow 08:00 → Save. RESTORE AT ONCE to the captured value (the field only holds minutes — restore to the minute) → Save.", "After saving: “<b>The contact SLA is paused until {date time} — no claim or transfer starts a clock before then.</b>” After the restore the paused line is gone, “Changed by Chau Chau on {date}”."),
    S("AH3", "ADMIN", "<code>/settings</code> → “Deadline by lead source” → ô <b>Webinar</b>: chụp giá trị (seed 24) → đặt <code>2</code> → Save → TRẢ LẠI đúng giá trị đã chụp → Save. “Neglect colouring”: Amber <code>3</code>, Red <code>2</code> (KHÔNG lưu) → tải lại trang.", "Webinar lưu được, “Changed by Chau Chau on {ngày}”; trả lại đúng giá trị cũ. Neglect: “<b>Red must come after amber</b>” / “Mốc đỏ phải sau mốc vàng”, Save mờ; tải lại vẫn 3 / 7.", "<code>/settings</code> → “Deadline by lead source” → <b>Webinar</b> box: screenshot the value (seed 24) → set <code>2</code> → Save → RESTORE the captured value → Save. “Neglect colouring”: Amber <code>3</code>, Red <code>2</code> (do NOT save) → reload.", "Webinar saves, “Changed by Chau Chau on {date}”; restored to the old value. Neglect: “<b>Red must come after amber</b>”, Save disabled; after reload still 3 / 7."),
    S("AH4", "ADMIN", "<code>/settings</code> → “Reminders &amp; notifications” → <b>Remind cooldown</b> = <code>59</code> → Save → TRẢ LẠI <code>60</code> → Save. “<b>Default follow-up distance</b>” chọn 2 ngày → TRẢ LẠI chọn 1 ngày.", "Cooldown: “Setting saved”, rồi về 60. Default follow-up distance <b>lưu ngay khi chọn</b> (không có nút Save): toast mỗi lần; cuối cùng = 1.", "<code>/settings</code> → “Reminders &amp; notifications” → <b>Remind cooldown</b> = <code>59</code> → Save → RESTORE <code>60</code> → Save. “<b>Default follow-up distance</b>” pick 2 days → RESTORE pick 1 day.", "Cooldown: “Setting saved”, then back to 60. Default follow-up distance <b>saves on pick</b> (no Save button): a toast each time; ends at 1."),
    S("AH5", "REC", "Recruiter → <b>Templates</b> → <b>New template / Template mới</b> → Scope <b>Team</b>, Type <code>SMS</code>, Name <code>QA reject 1010</code>, Body <code>QA test</code> → <b>Create draft</b> → <b>Submit for review / Gửi duyệt</b>. Di chuột lên nút Approve của nó. Rồi Manager → Templates → dòng IN_REVIEW → <b>Reject / Trả lại</b>. TRẢ LẠI: recruiter → <b>Submit for review</b> lần nữa → Manager → <b>Approve / Duyệt</b> → recruiter (hoặc Manager) → <b>Retire / Cho nghỉ</b> (Retire chỉ có khi ACTIVE).", "Recruiter: “Template created”, “\"QA reject 1010\" sent for review”; Approve mờ “Publishing needs the TEMPLATE_APPROVE grant (managers)”. Manager Reject: KHÔNG có hộp, toast “<b>\"QA reject 1010\" sent back to draft</b>” / “Đã trả \"QA reject 1010\" về bản nháp”; recruiter thấy DRAFT. Approve: “\"QA reject 1010\" is now ACTIVE”; Retire: “\"QA reject 1010\" retired”.", "Recruiter → <b>Templates</b> → <b>New template</b> → Scope <b>Team</b>, Type <code>SMS</code>, Name <code>QA reject 1010</code>, Body <code>QA test</code> → <b>Create draft</b> → <b>Submit for review</b>. Hover its Approve button. Then Manager → Templates → the IN_REVIEW row → <b>Reject</b>. RESTORE: recruiter → <b>Submit for review</b> again → Manager → <b>Approve</b> → <b>Retire</b> (Retire only exists on ACTIVE).", "Recruiter: “Template created”, “\"QA reject 1010\" sent for review”; Approve disabled “Publishing needs the TEMPLATE_APPROVE grant (managers)”. Manager Reject: NO dialog, toast “<b>\"QA reject 1010\" sent back to draft</b>”; the recruiter sees DRAFT. Approve: “\"QA reject 1010\" is now ACTIVE”; Retire: “\"QA reject 1010\" retired”."),
    S("AH6", "MGR", "<code>/audit</code> → bộ lọc loại lần lượt: Owner changes, Stage moves, Merges, Offer events, Conversation access granted, Conversation access revoked, Checklist template edits, Sponsorship changes, Production number edits → bộ lọc người thao tác = QA Test Recruiter → “25 / page” → <b>Export CSV / Xuất CSV</b> → một dòng có hồ sơ → <b>Open / Mở</b>.", "Mỗi loại lọc đúng (URL <code>type=</code>), rỗng thì “No events match”. Người thao tác: URL <code>actor=</code>. File CSV tải về là trang hiện tại, cột id (không phải tên). Open mở khung hồ sơ.", "<code>/audit</code> → type filter in turn: Owner changes, Stage moves, Merges, Offer events, Conversation access granted, Conversation access revoked, Checklist template edits, Sponsorship changes, Production number edits → actor = QA Test Recruiter → “25 / page” → <b>Export CSV</b> → a row with a candidate → <b>Open</b>.", "Each type filters (URL <code>type=</code>), empty shows “No events match”. Actor: URL <code>actor=</code>. The CSV is the current page with ids (not names). Open opens the candidate drawer."),
    S("AH7", "ADMIN", "<code>/permissions</code> → Access → dòng <code>role-losupport</code> → <b>Edit</b> → tick thêm một quyền không thuộc vai (vd AUDIT_VIEW) → Reason = <code>abc</code> → rồi <code>QA AH7 temporary override</code> → <b>Save</b>. Bỏ tick lại → reason <code>QA AH7 restore override</code> → Save. Tick “Grant ADMIN” → đọc hộp → Cancel. Mở dòng của chính chauchau.", "Ô tick hiện “added / thêm riêng”. Reason 3 ký tự: “A few more words, please — this is what the next person reads.”, Save mờ (tối thiểu 8 ký tự). Lưu: “Access updated.” / “Đã cập nhật quyền.”. Trả lại xong: không còn “added”. Grant ADMIN: “ADMIN grants EVERY permission, including RBAC_MANAGE — … Continue?” → Cancel, không cấp. Dòng chính mình: “Revoke all access” mờ “You cannot revoke your own access from here”, không có ô chọn hàng.", "<code>/permissions</code> → Access → the <code>role-losupport</code> row → <b>Edit</b> → tick a permission outside the role (e.g. AUDIT_VIEW) → Reason = <code>abc</code> → then <code>QA AH7 temporary override</code> → <b>Save</b>. Untick it → reason <code>QA AH7 restore override</code> → Save. Tick “Grant ADMIN” → read the dialog → Cancel. Open chauchau's own row.", "The tick shows “added”. A 3-character reason: “A few more words, please — this is what the next person reads.”, Save disabled (min 8 characters). Save: “Access updated.”. After the restore no “added” remains. Grant ADMIN: “ADMIN grants EVERY permission, including RBAC_MANAGE — … Continue?” → Cancel, nothing granted. Own row: “Revoke all access” disabled “You cannot revoke your own access from here”, no row checkbox."),
    S("AH8", "ADMIN", "<code>/permissions</code> → dòng <code>role-licensing</code> → Edit → <b>Revoke all access / Thu hồi toàn bộ quyền</b> → xác nhận. Đăng nhập role-licensing → My work today. TRẢ LẠI: Give access to someone → role-licensing → LICENSING → Give access.", "Hộp “Revoke this person's access entirely? They keep their company account and lose this app.” → “Access revoked.” / “Đã thu hồi quyền.”. role-licensing: “Could not load your queue”. Trả lại: “1 updated.”, dòng LICENSING trở lại. (Người còn giữ lead đang mở thì bị từ chối thu hồi: “… still holds N active candidate(s) — transfer them first …”.)", "<code>/permissions</code> → the <code>role-licensing</code> row → Edit → <b>Revoke all access</b> → confirm. Sign in as role-licensing → My work today. RESTORE: Give access to someone → role-licensing → LICENSING → Give access.", "“Revoke this person's access entirely? They keep their company account and lose this app.” → “Access revoked.”. role-licensing: “Could not load your queue”. Restore: “1 updated.”, the LICENSING row is back. (Someone still holding open leads is refused: “… still holds N active candidate(s) — transfer them first …”.)"),
    S("AH9", "ADMIN", "<code>/permissions</code> → tab <b>Program members / Thành viên chương trình</b> → CHỈ một dòng thành viên QA dùng một lần (KHÔNG phải “HH Test Headhunter”, không phải người thật) → mở “Show matching accounts” → <b>Reject / Từ chối</b> → lý do <code>abc</code> rồi <code>QA AH9 not this person</code> → xác nhận. <b>Từ chối KHÔNG hoàn tác được</b> (không có nút bỏ từ chối; thành viên bị ẩn tới khi đổi email) → không có thành viên QA dùng một lần → <b>Bỏ</b>.", "Lý do &lt;4 ký tự: “Write at least 4 characters.”. Toast “The match for {name} was rejected.” / “Đã từ chối tài khoản khớp với {name}.”; dòng ẩn, trên danh sách “{n} members are hidden because their match was rejected.” Unlink chỉ hiện với thành viên bị tạm ngưng — không test trên staging.", "<code>/permissions</code> → <b>Program members</b> tab → ONLY a disposable QA member row (NOT “HH Test Headhunter”, not a real person) → expand “Show matching accounts” → <b>Reject</b> → reason <code>abc</code> then <code>QA AH9 not this person</code> → confirm. <b>Rejecting can NOT be undone</b> (no un-reject; the member stays hidden until their email changes) → no disposable QA member → <b>Skip</b>.", "Reason &lt;4 characters: “Write at least 4 characters.”. Toast “The match for {name} was rejected.”; the row hides, the list says “{n} members are hidden because their match was rejected.” Unlink only shows for suspended members — not tested on staging."),
    S("AH10", "ANY", "Header → <b>Discovery / Khám phá</b> → <b>Arrange apps / Sắp xếp ứng dụng</b> → kéo một app sang vị trí khác → <b>Done / Xong</b> → tải lại → TRẢ LẠI: kéo app về chỗ cũ → Done. Bấm − trên một app trong Favorites → + để thêm lại. Khối tên (góc phải) → <b>Linked apps / Ứng dụng đã liên kết</b> → “Show N more / Xem thêm N” → “Show less / Thu gọn” → <b>Manage account / Quản lý tài khoản</b>.", "Thứ tự giữ sau khi tải lại. − bỏ khỏi Favorites, + thêm lại (trả về như cũ). Linked apps mở / thu đúng. Manage account mở trang tài khoản chung.", "Header → <b>Discovery</b> → <b>Arrange apps</b> → drag an app elsewhere → <b>Done</b> → reload → RESTORE: drag the app back → Done. − on a Favorites app → + to add it back. Name block (top right) → <b>Linked apps</b> → “Show N more” → “Show less” → <b>Manage account</b>.", "The order survives a reload. − removes from Favorites, + adds it back (restored). Linked apps expand / collapse. Manage account opens the shared account page."),
    S("AH11", "ANY", "Đang đăng nhập: mở <code>recruit.viet18.com/auth/callback?code=bogus</code>. Rồi <code>recruit.viet18.com/login?next=/pipeline</code>. Rồi Chrome → Settings → Languages: đưa Tiếng Việt lên đầu, xoá cookie <code>NEXT_LOCALE</code> của recruit.viet18.com (DevTools → Application → Cookies) → mở <code>recruit.viet18.com/candidates/7d05e871-b86d-4f60-83ec-aad1eba80358</code>. TRẢ LẠI ngôn ngữ trình duyệt.", "Callback: “<b>Sign-in couldn't be completed</b>” / “Không thể hoàn tất đăng nhập” + “This sign-in link is invalid or has expired. Please sign in again.” + nút “Back to sign in / Quay lại đăng nhập”. <code>/login?next=/pipeline</code> → thẳng tới Pipeline. Không cookie + trình duyệt ưu tiên vi → giao diện tiếng Việt kể cả link sâu; cookie có thì cookie thắng.", "Signed in: open <code>recruit.viet18.com/auth/callback?code=bogus</code>. Then <code>recruit.viet18.com/login?next=/pipeline</code>. Then Chrome → Settings → Languages: move Vietnamese to the top, delete recruit.viet18.com's <code>NEXT_LOCALE</code> cookie (DevTools → Application → Cookies) → open <code>recruit.viet18.com/candidates/7d05e871-b86d-4f60-83ec-aad1eba80358</code>. RESTORE the browser language.", "Callback: “<b>Sign-in couldn't be completed</b>” + “This sign-in link is invalid or has expired. Please sign in again.” + “Back to sign in”. <code>/login?next=/pipeline</code> → straight to Pipeline. No cookie + browser prefers vi → Vietnamese UI even on a deep link; a cookie wins over the browser."),
    S("AH12", "MGR", "Manager → <code>/reports</code> (tab Activity) → thẻ “<b>Unclaimed age — candidates nobody is working</b>” → rê chuột lên thanh.", "Có “Median wait / Chờ trung vị”, “Worst 10% wait / 10% chờ lâu nhất”, “Untouched &gt; 30d / Quá 30 ngày chưa ai nhận”; tooltip “{pct}% of active candidates have no recruiter”.", "Manager → <code>/reports</code> (Activity tab) → the “<b>Unclaimed age — candidates nobody is working</b>” card → hover the bar.", "Shows “Median wait”, “Worst 10% wait”, “Untouched &gt; 30d”; tooltip “{pct}% of active candidates have no recruiter”.")
  ] });

